<?php
require_once '../includes/rbac.php';exigirCargo(['administrador','diretor']);require_once '../conexao.php';require_once '../includes/flash.php';
if($_SERVER['REQUEST_METHOD']==='POST'){$nome=trim($_POST['nome']??'');$esp=trim($_POST['especialidade']??'');if(mb_strlen($nome)<3||mb_strlen($esp)<3)flash('error','Preencha nome e especialidade corretamente.');else try{$s=$pdo->prepare('INSERT INTO profissionais(nome,especialidade) VALUES(?,?)');$s->execute([$nome,$esp]);flash('success','Profissional adicionado com sucesso.');}catch(Throwable $e){flash('error','Não foi possível adicionar o profissional.');}header('Location: profissionais.php');exit;}
try{$prof=$pdo->query('SELECT * FROM profissionais ORDER BY nome')->fetchAll();}catch(Throwable $e){$prof=[];flash('error','Não foi possível carregar os profissionais.');}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Profissionais | Espaço Aura</title><link rel="stylesheet" href="../css/style.css"></head><body><header class="header"><div class="container nav"><a href="index.php" class="brand"><img src="../img/logo-aura-oficial.png" alt="Espaço Aura"></a><a class="back-link" href="index.php">← Painel</a></div></header><main class="panel-page"><div class="container"><h1 class="admin-title">Profissionais</h1><?php mostrarFlash();?><form method="post" class="form-card admin-form"><label>Nome</label><input name="nome" maxlength="100" required><label>Especialidade</label><select name="especialidade" required><option value="">Selecione</option><option>Psicoterapia</option><option>Fonoterapia infantil</option><option>Nutrição</option><option>Exame impedanciometria</option><option>Clínica geral</option></select><button class="btn" type="submit">Adicionar profissional</button></form><div class="table-wrapper"><table><thead><tr><th>Nome</th><th>Especialidade</th><th>Status</th></tr></thead><tbody><?php foreach($prof as $p):?><tr><td><?=htmlspecialchars($p['nome'])?></td><td><?=htmlspecialchars($p['especialidade'])?></td><td><?=$p['ativo']?'Ativo':'Inativo'?></td></tr><?php endforeach;?></tbody></table></div></div></main><script src="../js/app.js"></script></body></html>
